def visual(p, prefix='', mode=''):
    slug = p['slug']
    if p.get('image'):
        if slug == 'upi-recovery':
            return f'<div class="project-visual visual-upi {mode}"><span class="visual-label">Report a wrong UPI payment</span><img src="{prefix}assets/images/{p["image"]}" alt="{e(p["alt"])}" loading="lazy" width="572" height="1600"><span class="visual-foot">Independent product concept</span></div>'
        labels = {'cercit': ('cercit / credit review', 'Working demo · synthetic customer data'), 'hiremate': ('hiremate / role-specific practice', 'Strategy and clickable prototype'), 'coins': ('world of coins / collection catalogue', 'The public collection catalogue')}
        bar, caption = labels.get(slug, (p['title'], p['status']))
        width, height = {'cercit': (1265, 712), 'hiremate': (1920, 1140), 'coins': (1265, 712)}.get(slug, (1600, 950))
        loading = 'loading="eager" fetchpriority="high"' if mode == 'hero-preview' else 'loading="lazy"'
        return f'<div class="project-visual visual-{slug} {mode}"><div class="browser-frame"><div class="browser-bar"><span aria-hidden="true">● ● ●</span><span>{e(bar)}</span><span aria-hidden="true">↗</span></div><img src="{prefix}assets/images/{p["image"]}" alt="{e(p["alt"])}" {loading} width="{width}" height="{height}"></div><span class="visual-foot">{e(caption)}</span></div>'
    if slug == 'pagefit':
        inner = '<div class="paper-pair"><div class="paper paper-before"><span>Before</span><b>Study notes</b><i></i><i></i><i></i><i></i><em>Stranded heading</em></div><span class="paper-arrow" aria-hidden="true">→</span><div class="paper paper-after"><span>After</span><b>Study notes</b><i></i><i></i><i></i><i></i><b>Next section</b><i></i><i></i><i></i></div></div>'
    elif slug == 'pm-portfolio':
        inner = '<span class="diagram-kicker">Five course sessions, five deliverables.</span><div class="flow"><span>Learn<br><small>Session notes</small></span><b aria-hidden="true">→</b><span>Apply<br><small>A real product</small></span><b aria-hidden="true">→</b><span>Publish<br><small>One piece each</small></span></div><div class="local-label">Course deliverables · Masai x iHUB DivyaSampark IIT Roorkee</div>'
    elif slug == 'coins':
        inner = '<div class="coin-illustration" aria-hidden="true"><div class="coin">1<span>COLLECTION</span></div><div class="coin coin-small">½<span>STORIES IN METAL</span></div></div><div class="collection-path">Country <span>›</span> Issuer <span>›</span> Ruling authority</div>'
    else:
        inner = '<span class="diagram-kicker">Connect WPL players, matches and squads.</span><div class="data-join"><span>Match<br><small>match_id</small></span><b aria-hidden="true">↔</b><span>Player<br><small>player_id</small></span><b aria-hidden="true">↔</b><span>Squad<br><small>season + team</small></span></div><div class="local-label">Performance + season membership + acquisition</div>'
    return f'<div class="project-visual illustration visual-{slug} {mode}" role="img" aria-label="Illustrative diagram for {e(p["title"])}">{inner}<span class="visual-foot">Illustration of the approach</span></div>'

def card(p, number='', feature=False):
    return f'''<article class="project-card{' feature-card' if feature else ''}" data-project-card data-category="{p['category']}" data-search="{e(p['title']+' '+p['category']+' '+p['kicker']+' '+p['summary']+' '+p['status'])}"><a class="visual-link" tabindex="-1" aria-hidden="true" href="projects/{p['slug']}.html">{visual(p)}</a><div class="card-copy"><div class="project-meta"><span>{number or p['category']}</span><span class="status{' status-wip' if p['status'] == 'In progress' else ''}">{p['status']}</span></div><h3><a href="projects/{p['slug']}.html">{e(p['title'])} <span aria-hidden="true">↗</span></a></h3><p class="card-kicker">{e(p['kicker'])}</p><p>{e(p['summary'])}</p><a class="text-link" href="projects/{p['slug']}.html">Read the case study <span aria-hidden="true">→</span></a></div></article>'''

home = '''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">Vehicle finance · Product management · Chennai</p><h1>Sameer Shreenivas<br>Mittimani.</h1><p class="hero-subtitle">Twelve years in vehicle finance.<br>Now building toward product management.</p><p class="hero-intro">I'm a Deputy Manager at Sundaram Finance. I started at a branch counter in 2014 and now work in national auto retail analytics. The projects here are how I'm putting that experience into product work.</p><div class="hero-actions"><a class="button" href="#selected-work">See my work <span aria-hidden="true">↓</span></a><a class="text-link" href="#journey">Read my story <span aria-hidden="true">→</span></a></div><p class="hero-context">Studying Product Management with Applied AI through Masai and iHUB DivyaSampark, IIT Roorkee.</p></div><div class="hero-work"><div class="hero-chart" aria-hidden="true"><svg class="viz" viewBox="0 0 440 160" fill="none" xmlns="http://www.w3.org/2000/svg" role="presentation" focusable="false"><defs><linearGradient id="vizFill" x1="0" y1="0" x2="0" y2="1"><stop class="viz-stop-top" offset="0%"/><stop class="viz-stop-bottom" offset="100%"/></linearGradient></defs><g class="viz-grid"><line x1="56" y1="29" x2="404" y2="29"/><line x1="56" y1="59" x2="404" y2="59"/><line x1="56" y1="89" x2="404" y2="89"/><line x1="56" y1="119" x2="404" y2="119"/></g><path class="viz-axis" pathLength="1" d="M56 8 V149 H404"/><g class="viz-bars"><rect x="79" y="115" width="26" height="34" rx="3"/><rect x="147" y="97" width="26" height="52" rx="3"/><rect x="215" y="106" width="26" height="43" rx="3"/><rect x="283" y="78" width="26" height="71" rx="3"/><rect x="351" y="60" width="26" height="89" rx="3"/></g><path class="viz-area" d="M92 102 L160 83 L228 91 L296 63 L364 40 L364 149 L92 149 Z" fill="url(#vizFill)"/><path class="viz-line" pathLength="1" d="M92 102 L160 83 L228 91 L296 63 L364 40"/><path class="viz-proj" d="M364 40 L404 26"/><g class="viz-nodes"><circle cx="92" cy="102" r="4.5"/><circle cx="160" cy="83" r="4.5"/><circle cx="228" cy="91" r="4.5"/><circle cx="296" cy="63" r="4.5"/><circle cx="364" cy="40" r="4.5"/></g><circle class="viz-pulse" cx="364" cy="40" r="9"/></svg><span class="hero-chart-note">An illustration of a trend line, not real data.</span></div><div class="hero-journey"><p class="journey-title">How I got here</p><ol class="journey-list"><li><time datetime="2014">2014</time><div><strong>Customer support</strong><span>Shahpur</span></div></li><li><time datetime="2015">2015</time><div><strong>Branch accounts</strong><span>Bijapur</span></div></li><li><time datetime="2022">2022</time><div><strong>Working capital finance</strong><span>Bellary</span></div></li><li><time datetime="2024">2024–now</time><div><strong>National auto retail</strong><span>Chennai</span></div></li></ol><a class="text-link" href="projects/cercit.html">Explore CERCIT, my lending demo <span aria-hidden="true">↗</span></a></div></div></section>
<section class="about-preview wrap" id="journey"><div class="about-image"><img src="assets/images/sameer.jpg" alt="Sameer Mittimani" width="900" height="900" loading="lazy"><span>Originally from Dharwad. Now in Chennai.</span></div><div><p class="eyebrow">My journey</p><h2>Why I'm moving into product.</h2><p>At the branch, I worked on loan files and customer follow-up. In working capital finance, I helped roll out a lending product. Today, I use enquiry and market data to understand what's happening across the retail business.</p><p>Those roles made me interested in how the process itself is designed: what information someone needs, where a file gets stuck, and what would help them take the next step.</p><p>I'm learning product management alongside my job. CERCIT is one way I'm applying it: a loan-review demo where a credit officer can see the documents, policy checks and reasons behind a recommendation.</p><a class="text-link" href="about.html">More about me <span aria-hidden="true">↗</span></a></div></section>
<section class="career-section wrap" id="career"><div class="section-heading"><div><p class="eyebrow">Sundaram Finance · Since 2014</p><h2>Four roles. A wider view of lending.</h2></div><a class="text-link" href="assets/resume.pdf">Read my resume (PDF) <span aria-hidden="true">↗</span></a></div><div class="career-grid"><article><p class="career-date">April 2024–present · Chennai</p><h3>Deputy Manager, Auto National Retail Team</h3><p>I work on enquiry lifecycles, Vahan market analysis and management dashboards. The work connects what happens in branches with the national retail business.</p></article><article><p class="career-date">April 2022–March 2024 · Bellary</p><h3>Deputy Manager, Working Capital Finance</h3><p>I worked on lending-product rollout, including Bulk Diesel Finance, and coordinated with branches and channel partners.</p></article><article><p class="career-date">August 2015–March 2022 · Bijapur</p><h3>Cashier, then Branch Accountant</h3><p>Branch accounts and loan operations put me close to the everyday work of documentation, repayments and customer follow-up. I became Branch Accountant in 2017.</p></article><article><p class="career-date">August 2014–August 2015 · Shahpur</p><h3>Customer Support Executive</h3><p>My first role covered loan processing, credit assessments and compliance work. This was where I learned how a loan file moves through a branch.</p></article></div></section>
<section class="selected-work wrap" id="selected-work"><div class="section-heading"><div><p class="eyebrow">Selected work</p><h2>What I've been building.</h2><p class="section-intro">A working lending demo, a payment-recovery concept and a banking interview prototype. Open a project to see the decisions behind it.</p></div><a class="text-link" href="work.html">All @@N@@ projects <span aria-hidden="true">↗</span></a></div>''' + card(P['cercit'],'Product & credit policy',True) + '<div class="secondary-projects">'+card(P['upi-recovery'],'Product design')+card(P['hiremate'],'Product strategy')+'</div></section>'
