filters = '<div class="work-controls" data-filters hidden><div class="filter-buttons" role="group" aria-label="Filter projects">'+''.join(f'<button data-filter="{value}" aria-pressed="{str(value == "all").lower()}">{label}</button>' for value,label in [('all','All work'),('product','Product'),('tools','Tools'),('analytics','Analytics'),('personal','Personal')])+'</div><label class="search-label"><span class="sr-only">Search projects</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><input id="workSearch" type="search" placeholder="Search projects" autocomplete="off"></label></div>'
